import datetime

def next_billing_date(start: datetime.date, months_ahead: int) -> datetime.date:
    if months_ahead == 0:
        return start
    new_year = start.year + (start.month - 1 + months_ahead) // 12
    new_month = (start.month - 1 + months_ahead) % 12 + 1
    day = start.day
    # Clamp day to last valid day of target month (handles short months/leap years)
    if new_month == 12:
        first_of_next = datetime.date(new_year + 1, 1, 1)
    else:
        first_of_next = datetime.date(new_year, new_month + 1, 1)
    last_day = (first_of_next - datetime.timedelta(days=1)).day
    if day > last_day:
        day = last_day
    return datetime.date(new_year, new_month, day)
